registerAttempts.script:
export const meta = {
  description: 'Two-stage cold probe: read notes.txt, then report its contents',
  params: {
    agents: {
      reader: { model: { type: 'string', default: 'default' }, effort: { type: 'enum', enum: ['low','medium','high'], default: 'low' }, timeoutMs: { type: 'number', default: 60000 } },
      reporter: { model: { type: 'string', default: 'default' }, effort: { type: 'enum', enum: ['low','medium','high'], default: 'low' }, timeoutMs: { type: 'number', default: 60000 } },
    },
  },
};
phase('read');
const notes = await agent('reader', { prompt: 'Read the file notes.txt and return its exact contents with no extra commentary.', allowedTools: ['Read'] });
phase('report');
return await agent('reporter', { prompt: 'In one short sentence, report the notes content you were given: ' + notes, allowedTools: [] });

